const rows = $input.all().map(item => item.json);

const now = Date.now();
const sevenDays = 7 * 24 * 60 * 60 * 1000;
const MAX_MESSAGES = 40; // batasi supaya prompt tidak membengkak

function getTime(value) {
  if (typeof value !== 'string' || !value.trim()) return NaN;
  const normalized = value.trim().replace(/([+-]\d{2}):(\d{2})$/, '$1$2');
  return Date.parse(normalized);
}

const weeklyRows = rows
  .filter(row => row.message && row.timestamp)
  .filter(row => {
    const time = getTime(row.timestamp);
    return Number.isFinite(time) && time <= now && now - time <= sevenDays;
  })
  .sort((a, b) => getTime(a.timestamp) - getTime(b.timestamp))
  .slice(-MAX_MESSAGES);

const trigger = $('Chat Trigger').first();
const binary = trigger.binary || {};

// hanya ambil file bertipe gambar
const imageBinary = {};
for (const [key, file] of Object.entries(binary)) {
  if (file && typeof file.mimeType === 'string' && file.mimeType.startsWith('image/')) {
    imageBinary[key] = file;
  }
}
const hasImage = Object.keys(imageBinary).length > 0;

let chatInput = (trigger.json.chatInput || '').toString().trim();
if (!chatInput && hasImage) {
  chatInput = 'Tolong analisis foto makanan ini: apa saja isinya, perkiraan kalori, protein, karbohidrat, dan lemaknya.';
}
if (!chatInput) {
  chatInput = 'Halo';
}

const history = weeklyRows.map(row => `${row.role}: ${row.message}`).join('\n');

const result = {
  json: {
    sessionId: 'ibu-profile-1',
    chatInput,
    hasImage,
    jumlahChatMingguIni: weeklyRows.length,
    history: history || 'Belum ada riwayat chat dalam 7 hari terakhir.'
  }
};
if (hasImage) result.binary = imageBinary;
return [result];

const out = $('AI Diet Assistant').first().json.output;
const answer = (typeof out === 'string' && out.trim())
  ? out
  : 'Maaf, jawaban AI belum tersedia. Silakan coba kirim ulang pesan atau fotonya.';
return [{ json: { output: answer } }];
